import { path } from '@servicenow/sdk-build-core'
import { getMergedRecordUpdates, unzipInputArray } from './test-utils'
import { createTestContext } from '../../test-utils'

describe('SetFlowVariables with Datapills Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('SetFlowVariables -> Fluent to XML', () => {
        test('SetFlowVariables with trigger datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            // Verify flow logic instances were created
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Find the setFlowVariables with trigger datapills
            const setVarsWithTrigger = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set flow variables from trigger datapills'
            )
            expect(setVarsWithTrigger).toBeDefined()

            // Parse the values
            const valuesJson = unzipInputArray(setVarsWithTrigger.values) as any

            // Verify variables array exists
            expect(valuesJson.variables).toBeDefined()
            expect(valuesJson.variables.length).toBeGreaterThan(0)

            // Find userName variable with trigger datapill
            const userNameVar = valuesJson.variables.find((v: any) => v.name === 'userName')
            expect(userNameVar).toBeDefined()
            expect(userNameVar.value).toContain('{{')
            expect(userNameVar.value).toContain('.current.sys_created_by}}')

            // Find incidentNumber variable
            const incidentNumVar = valuesJson.variables.find((v: any) => v.name === 'incidentNumber')
            expect(incidentNumVar).toBeDefined()
            expect(incidentNumVar.value).toContain('.current.number}}')

            // Find priority variable
            const priorityVar = valuesJson.variables.find((v: any) => v.name === 'priority')
            expect(priorityVar).toBeDefined()
            expect(priorityVar.value).toContain('.current.priority}}')

            // Find timestamp variable
            const timestampVar = valuesJson.variables.find((v: any) => v.name === 'timestamp')
            expect(timestampVar).toBeDefined()
            expect(timestampVar.value).toContain('.current.sys_created_on}}')

            // Find boolean variable (should be literal)
            const isActiveVar = valuesJson.variables.find((v: any) => v.name === 'isActive')
            expect(isActiveVar).toBeDefined()
            expect(isActiveVar.value).toBe('true')
        })

        test('SetFlowVariables with action output datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find the setFlowVariables with action output datapills
            const setVarsWithAction = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set flow variables from action output datapills'
            )
            expect(setVarsWithAction).toBeDefined()

            const valuesJson = unzipInputArray(setVarsWithAction.values) as any

            // Find recordId variable with action output datapill
            const recordIdVar = valuesJson.variables.find((v: any) => v.name === 'recordId')
            expect(recordIdVar).toBeDefined()
            expect(recordIdVar.value).toContain('{{')
            expect(recordIdVar.value).toContain('.record}}')
        })

        test('SetFlowVariables with flow variable datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find the setFlowVariables with flow variable datapills
            const setVarsWithFlowVars = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set flow variables from other flow variable datapills'
            )
            expect(setVarsWithFlowVars).toBeDefined()

            const valuesJson = unzipInputArray(setVarsWithFlowVars.values) as any

            // Find message variable with template expression containing flow variable datapills
            const messageVar = valuesJson.variables.find((v: any) => v.name === 'message')
            expect(messageVar).toBeDefined()
            expect(messageVar.value).toContain('{{flow_variable.userName}}')
            expect(messageVar.value).toContain('{{flow_variable.incidentNumber}}')
            expect(messageVar.value).toContain('User ')
            expect(messageVar.value).toContain(' created incident ')
        })

        test('SetFlowVariables with mixed literals and datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find the setFlowVariables with mixed values
            const setVarsMixed = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set flow variables with mixed datapills and literals'
            )
            expect(setVarsMixed).toBeDefined()

            const valuesJson = unzipInputArray(setVarsMixed.values) as any

            // Priority should be literal
            const priorityVar = valuesJson.variables.find((v: any) => v.name === 'priority')
            expect(priorityVar).toBeDefined()
            expect(priorityVar.value).toBe('1')

            // isActive should be flow variable datapill
            const isActiveVar = valuesJson.variables.find((v: any) => v.name === 'isActive')
            expect(isActiveVar).toBeDefined()
            expect(isActiveVar.value).toBe('{{flow_variable.isActive}}')

            // message should be template with datapills
            const messageVar = valuesJson.variables.find((v: any) => v.name === 'message')
            expect(messageVar).toBeDefined()
            expect(messageVar.value).toContain('Priority updated for')
            expect(messageVar.value).toContain('{{flow_variable.incidentNumber}}')
        })
    })

    describe('SetFlowVariables Structure and Format', () => {
        test('SetFlowVariables variables array structure', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const firstInstance = flowLogicInstances[0]

            const valuesJson = unzipInputArray(firstInstance.values) as any

            // Variables array should exist
            expect(valuesJson.variables).toBeDefined()
            expect(Array.isArray(valuesJson.variables)).toBe(true)

            // Each variable should have name, value, and displayValue
            valuesJson.variables.forEach((variable: any) => {
                expect(variable.name).toBeDefined()
                expect(variable.value).toBeDefined()
                expect(variable.displayValue).toBeDefined()
            })
        })

        test('SetFlowVariables backward compatibility inputs array', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const firstInstance = flowLogicInstances[0]

            const valuesJson = unzipInputArray(firstInstance.values) as any

            // Inputs array should exist for backward compatibility
            expect(valuesJson.inputs).toBeDefined()
            expect(Array.isArray(valuesJson.inputs)).toBe(true)

            // Should have same length as variables array
            expect(valuesJson.inputs.length).toBe(valuesJson.variables.length)
        })

        test('SetFlowVariables displayValue mirrors value for datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const setVarsWithTrigger = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set flow variables from trigger datapills'
            )

            const valuesJson = unzipInputArray(setVarsWithTrigger.values) as any

            // For datapills, displayValue should mirror value
            const userNameVar = valuesJson.variables.find((v: any) => v.name === 'userName')
            expect(userNameVar.value).toBe(userNameVar.displayValue)

            const incidentNumVar = valuesJson.variables.find((v: any) => v.name === 'incidentNumber')
            expect(incidentNumVar.value).toBe(incidentNumVar.displayValue)
        })
    })

    describe('SetFlowVariables with Datapills - Data Types', () => {
        test('SetFlowVariables with string datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const setVarsWithTrigger = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set flow variables from trigger datapills'
            )

            const valuesJson = unzipInputArray(setVarsWithTrigger.values) as any

            // String datapills
            const stringVars = ['userName', 'incidentNumber', 'timestamp']
            stringVars.forEach((varName) => {
                const variable = valuesJson.variables.find((v: any) => v.name === varName)
                expect(variable).toBeDefined()
                expect(variable.value).toContain('{{')
                expect(variable.value).toContain('}}')
            })
        })

        test('SetFlowVariables with integer datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const setVarsWithTrigger = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set flow variables from trigger datapills'
            )

            const valuesJson = unzipInputArray(setVarsWithTrigger.values) as any

            // Integer datapill
            const priorityVar = valuesJson.variables.find((v: any) => v.name === 'priority')
            expect(priorityVar).toBeDefined()
            expect(priorityVar.value).toContain('{{')
            expect(priorityVar.value).toContain('.priority}}')
        })

        test('SetFlowVariables with boolean datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const setVarsMixed = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set flow variables with mixed datapills and literals'
            )

            const valuesJson = unzipInputArray(setVarsMixed.values) as any

            // Boolean datapill
            const isActiveVar = valuesJson.variables.find((v: any) => v.name === 'isActive')
            expect(isActiveVar).toBeDefined()
            expect(isActiveVar.value).toBe('{{flow_variable.isActive}}')
        })

        test('SetFlowVariables with reference datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const setVarsWithAction = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set flow variables from action output datapills'
            )

            const valuesJson = unzipInputArray(setVarsWithAction.values) as any

            // Reference datapill from action output
            const recordIdVar = valuesJson.variables.find((v: any) => v.name === 'recordId')
            expect(recordIdVar).toBeDefined()
            expect(recordIdVar.value).toContain('.record}}')
        })
    })

    describe('SetFlowVariables with Datapills - Template Expressions', () => {
        test('SetFlowVariables with template containing datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const setVarsWithFlowVars = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set flow variables from other flow variable datapills'
            )

            const valuesJson = unzipInputArray(setVarsWithFlowVars.values) as any

            // Template expression with multiple datapills
            const messageVar = valuesJson.variables.find((v: any) => v.name === 'message')
            expect(messageVar).toBeDefined()

            // Should contain literal text
            expect(messageVar.value).toContain('User ')
            expect(messageVar.value).toContain(' created incident ')

            // Should contain datapills
            expect(messageVar.value).toContain('{{flow_variable.userName}}')
            expect(messageVar.value).toContain('{{flow_variable.incidentNumber}}')
        })

        test('SetFlowVariables template expression ordering', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const setVarsWithFlowVars = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set flow variables from other flow variable datapills'
            )

            const valuesJson = unzipInputArray(setVarsWithFlowVars.values) as any
            const messageVar = valuesJson.variables.find((v: any) => v.name === 'message')

            // Verify template structure: "User {{var1}} created incident {{var2}}"
            const userIndex = messageVar.value.indexOf('User ')
            const createdIndex = messageVar.value.indexOf(' created incident ')
            const userName = messageVar.value.indexOf('{{flow_variable.userName}}')
            const incidentNum = messageVar.value.indexOf('{{flow_variable.incidentNumber}}')

            // Verify ordering
            expect(userIndex).toBeLessThan(userName)
            expect(userName).toBeLessThan(createdIndex)
            expect(createdIndex).toBeLessThan(incidentNum)
        })
    })

    describe('SetFlowVariables with Datapills - Edge Cases', () => {
        test('Multiple setFlowVariables in single flow', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Should have at least 4 setFlowVariables instances
            expect(flowLogicInstances.length).toBeGreaterThanOrEqual(4)

            // Each should have valid variables
            flowLogicInstances.forEach((instance: any) => {
                const valuesJson = unzipInputArray(instance.values) as any
                expect(valuesJson.variables).toBeDefined()
                expect(valuesJson.variables.length).toBeGreaterThan(0)
            })
        })

        test('SetFlowVariables with empty string literal', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            // Verify all instances were created successfully
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)
        })

        test('SetFlowVariables datapill sources', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'set-flow-variables-datapills.now.ts', 'flow-logics')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Collect all variable values
            const allVariables = flowLogicInstances.flatMap((instance: any) => {
                const valuesJson = unzipInputArray(instance.values) as any
                return valuesJson.variables
            })

            // Should have datapills from trigger
            const hasTriggerDatapills = allVariables.some((v: any) => v.value.includes('.current.'))
            expect(hasTriggerDatapills).toBe(true)

            // Should have datapills from flow variables
            const hasFlowVarDatapills = allVariables.some((v: any) => v.value.includes('{{flow_variable.'))
            expect(hasFlowVarDatapills).toBe(true)

            // Should have datapills from action outputs
            const hasActionOutputDatapills = allVariables.some((v: any) => v.value.includes('.record}}'))
            expect(hasActionOutputDatapills).toBe(true)
        })
    })
})
